code='''def transform(grid):
    h,w=len(grid),len(grid[0]); vals={v for row in grid for v in row}
    counts={v:sum(row.count(v) for row in grid) for v in vals}
    marker=min((v for v in vals if v not in sorted(vals,key=lambda x:counts[x],reverse=True)[:2]), default=None)
    if marker is None: marker=min(vals)
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    mr=min(r for r,c in pts); mc=min(c for r,c in pts); shape={(r-mr,c-mc) for r,c in pts}
    out=[row[:] for row in grid]
    for flip in (1,-1):
      for k in range(4):
        q=[]
        for r,c in shape:
          r,c=r,flip*c
          for _ in range(k): r,c=c,-r
          q.append((r,c))
        ar=min(r for r,c in q); ac=min(c for r,c in q); sh={(r-ar,c-ac) for r,c in q}
        hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
        for i in range(h-hh+1):
          for j in range(w-ww+1):
            if all(grid[i+r][j+c]==0 for r,c in sh):
              for r,c in sh: out[i+r][j+c]=marker
    return out
'''
